#!/usr/bin/env node
const fs = require('fs');
const crypto = require('crypto');
function arg(name, fallback=null) { const i=process.argv.indexOf(name); return i>=0 ? process.argv[i+1] : fallback; }
const input=arg('--input', process.argv[2]);
const out=arg('--out','final_assessment_attempt.json');
const learnerId=arg('--learner-id','anonymous');
const attempt=arg('--attempt','1');
const requested=Math.max(8, Number(arg('--questions','50')));
const mode=arg('--mode','learner');
if (!input) { console.error('Usage: node randomize_final_assessment.js <assessment.json> --learner-id ID --attempt N --questions 50 --out attempt.json'); process.exit(1); }
const assessment=JSON.parse(fs.readFileSync(input,'utf8'));
const bank=assessment.finalAssessment.questionBank;
const seedMaterial=`${learnerId}|${attempt}|${crypto.randomBytes(16).toString('hex')}`;
let seed=crypto.createHash('sha256').update(seedMaterial).digest('hex');
function rand(){ seed=crypto.createHash('sha256').update(seed).digest('hex'); return parseInt(seed.slice(0,8),16)/0xffffffff; }
function shuffle(a){ a=[...a]; for(let i=a.length-1;i>0;i--){const j=Math.floor(rand()*(i+1)); [a[i],a[j]]=[a[j],a[i]];} return a; }
const selected=[];
const selectedIds=new Set();
function addOne(pool){ const candidates=shuffle(pool).filter(q=>!selectedIds.has(q.id)); if(!candidates.length) return; selected.push(candidates[0]); selectedIds.add(candidates[0].id); }
// Guarantee at least one question from every domain and every assessment format.
for (const domainId of [...new Set(bank.map(q=>q.domainId))]) addOne(bank.filter(q=>q.domainId===domainId));
for (const type of [...new Set(bank.map(q=>q.type))]) addOne(bank.filter(q=>q.type===type));
// Fill remaining positions from the unused bank.
selected.push(...shuffle(bank.filter(q=>!selectedIds.has(q.id))).slice(0, Math.max(0, requested-selected.length)));
const attemptQuestions=shuffle(selected).slice(0,requested).map((q,index)=>{
  const copy=JSON.parse(JSON.stringify(q)); copy.position=index+1;
  if(Array.isArray(copy.options)) copy.options=shuffle(copy.options);
  if(mode!=='teacher') { delete copy.answerKey; delete copy.explanation; delete copy.rubric; }
  return copy;
});
const result={assessmentId:assessment.finalAssessment.id,learnerId,attempt:Number(attempt),mode,questionCount:attemptQuestions.length,generatedAt:new Date().toISOString(),seedFingerprint:crypto.createHash('sha256').update(seedMaterial).digest('hex').slice(0,16),coverage:{domains:[...new Set(attemptQuestions.map(q=>q.domainId))],types:[...new Set(attemptQuestions.map(q=>q.type))]},questions:attemptQuestions};
fs.writeFileSync(out,JSON.stringify(result,null,2)+'\n');
console.log(`Created ${attemptQuestions.length}-question ${mode} attempt: ${out}`);
